def max_removals(s):
    n = len(s)
    dp = [0] * n

    for i in range(1, n):
        if s[i] == chr(ord(s[i-1]) + 1):
            dp[i] = dp[i-1] + 1
        else:
            dp[i] = dp[i-1]

    for i in range(n-2, -1, -1):
        if s[i] == chr(ord(s[i+1]) + 1):
            dp[i] = max(dp[i], dp[i+1] + 1)
        else:
            dp[i] = max(dp[i], dp[i+1])

    return dp[0]

# Read input
import sys
input = sys.stdin.read
data = input().split()
n = int(data[0])
s = data[1]

# Compute and print the result
print(max_removals(s))
